export const allChapters = curso.flatMap((p) =>
  p.chapters.map((c) => ({ ...c, partSlug: p.slug, partTitle: p.title }))
);

export function getChapter(slug: string) {
  const i = allChapters.findIndex((c) => c.slug === slug);
  if (i === -1) return null;
  return {
    chapter: allChapters[i],
    prev: allChapters[i - 1] ?? null,
    next: allChapters[i + 1] ?? null,
    index: i,
    total: allChapters.length,
  };
}
